const APP_VERSION='0.14.1';
const KEYS={profile:'hh_proto_v092_profile',plan:'hh_proto_v092_plan',state:'hh_proto_v092_state',theme:'hh_proto_theme',chat:'hh_proto_v092_chat',lang:'hh_proto_language',device:'hh_device_id'};
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const parseJSON=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}};
const saveJSON=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch{}};
const toast=msg=>{const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(window.__toast);window.__toast=setTimeout(()=>el.classList.remove('show'),1800)};
let lang=localStorage.getItem(KEYS.lang)||'';
const L=(pt,en,es)=>lang==='pt-BR'?pt:lang==='es'?es:en;
const locale=()=>lang==='pt-BR'?'pt-BR':lang==='es'?'es-ES':'en-US';
const hasMeaningfulText=x=>{const t=String(x||'').trim().toLowerCase();return !!t&&!['none','nenhuma','nenhum','não','nao','no','n/a','na','ninguna','ninguno','ningún'].includes(t)};
const freshState=()=>({startedAt:'',cycleNumber:1,week:1,nav:'HOME',trainingMode:'gym',completedExercises:{},completedSessions:{},habits:{},checkins:[],mealWeek:1,mealDay:0,mealSlot:0,audit:null,labQA:null,traceLab:[],baseline:null,checkpoint:null,finalMark:null,postWorkout:{pending:false,session:'',mindDone:false},nextCycle:null,cycleHistory:[],sync:{persistent:false,lastSyncedAt:''}});
const dayKey=ts=>{const d=new Date(ts);return Number.isFinite(d.getTime())?`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`:''};
const normalizeDailyCheckins=rows=>{const seen=new Set();return (Array.isArray(rows)?rows:[]).filter(Boolean).slice().sort((a,b)=>Date.parse(b.ts||0)-Date.parse(a.ts||0)).map(x=>({...x,dayKey:/^\d{4}-\d{2}-\d{2}$/.test(String(x.dayKey||''))?x.dayKey:dayKey(x.ts)})).filter(x=>{const k=x.dayKey;if(!k||seen.has(k))return false;seen.add(k);return ['energy','sleep','training','nutrition'].every(f=>Number.isFinite(Number(x[f]))&&Number(x[f])>=1&&Number(x[f])<=5)}).slice(0,90)};
const canonicalSessionIdentity=k=>{const m=String(k||'').match(/^w(\d+):(?:(?:gym|home):)?(.+)$/);return m?('w'+m[1]+':'+m[2]):String(k||'')};
const normalizeSessionCompletions=src=>{const out={};for(const [k,v] of Object.entries(src||{}))if(v===true)out[canonicalSessionIdentity(k)]=true;return out};
const normalizeState=x=>{const merged={...freshState(),...(x||{}),postWorkout:{...freshState().postWorkout,...(x?.postWorkout||{})},sync:{...freshState().sync,...(x?.sync||{})}};merged.checkins=normalizeDailyCheckins(merged.checkins);merged.completedSessions=normalizeSessionCompletions(merged.completedSessions);merged.traceLab=(Array.isArray(merged.traceLab)?merged.traceLab:[]).filter(Boolean).slice(-40);merged.cycleHistory=(Array.isArray(merged.cycleHistory)?merged.cycleHistory:[]).filter(Boolean).slice(-120);return merged};
const freshOnboardingDraft=()=>({language:lang||'en-US',name:'',primaryGoal:'',level:'',days:[],location:'',minutes:'',preferredTime:'',units:'imperial',height:'',weight:'',targetWeight:'',meals:'',cooking:'',foodPreferences:'',dislikes:'',allergies:'',proteinPreferences:[],grainPreferences:[],veggiePreferences:[],openToOtherVeggies:true,foodStyles:[],mealPrepPreference:'',eatOutFrequency:'',sleep:'',stress:'',currentPain:'',painAreas:[],redFlags:'',professionalRestrictions:'',professionalRestrictionScope:'',safetyDetails:'',accuracy:false,prototypeAck:false});
let profile=parseJSON(KEYS.profile,null),plan=parseJSON(KEYS.plan,null),state=normalizeState(parseJSON(KEYS.state,freshState()));
if(profile)profile={...freshOnboardingDraft(),...profile,days:[...(profile.days||[])],proteinPreferences:[...(profile.proteinPreferences||[])],grainPreferences:[...(profile.grainPreferences||[])],veggiePreferences:[...(profile.veggiePreferences||[])],foodStyles:[...(profile.foodStyles||[])],painAreas:[...(profile.painAreas||[])]};
let onboardStep=0,onboardingDraft=freshOnboardingDraft();

