const DAY_NAMES={Mon:['Seg','Mon','Lun'],Tue:['Ter','Tue','Mar'],Wed:['Qua','Wed','Mié'],Thu:['Qui','Thu','Jue'],Fri:['Sex','Fri','Vie'],Sat:['Sáb','Sat','Sáb'],Sun:['Dom','Sun','Dom']};
