const prefChips=(type,field)=>`<div class="chipGrid">${PREF_OPTIONS[type].map(([k,l])=>`<button type="button" class="chipChoice ${onboardingDraft[field].includes(k)?'active':''}" data-multi="${field}" data-val="${k}">${L(...l)}</button>`).join('')}</div>`;
