function applyTheme(t){document.body.dataset.theme=t;localStorage.setItem(KEYS.theme,t);document.querySelector('meta[name="theme-color"]').setAttribute('content',t==='dark'?'#060606':'#f8f4ec')}
applyTheme(localStorage.getItem(KEYS.theme)||'light');
function bindThemeButtons(){$$('[data-theme-toggle]').forEach(b=>b.onclick=()=>{applyTheme(document.body.dataset.theme==='dark'?'light':'dark');applyStaticTranslations();if(profile&&plan)renderAll()})}
bindThemeButtons();

async function api(path,body){const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),30000);try{const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:ctl.signal});const data=await r.json().catch(()=>({}));if(!r.ok)throw new Error(data.error||L('Falha no servidor','Server error','Error del servidor'));return data}catch(e){if(e?.name==='AbortError')throw new Error(L('A solicitação demorou demais. Tente novamente.','The request timed out. Try again.','La solicitud tardó demasiado. Inténtalo de nuevo.'));throw e}finally{clearTimeout(timer)}}
let authMeta={authenticated:false,provider:null},systemStatus={aiProviders:[],aiRoutes:[],netlifyGateway:false,gatewayOnly:true,directAIAllowed:false,supabaseState:false,sessionProvider:null};
async function refreshSystemStatus(){try{const r=await fetch('/api/status',{cache:'no-store'});if(r.ok)systemStatus=await r.json()}catch{}return systemStatus}
async function authStatus(){try{const r=await fetch('/api/auth',{cache:'no-store'});authMeta=r.ok?await r.json():{authenticated:false,provider:null};return !!authMeta.authenticated}catch{authMeta={authenticated:false,provider:null};return false}}
function getDeviceId(){let id=localStorage.getItem(KEYS.device)||'';if(!/^[A-Za-z0-9._:-]{16,128}$/.test(id)){id=(crypto.randomUUID?crypto.randomUUID():`hh-${Date.now()}-${Math.random().toString(36).slice(2)}`);localStorage.setItem(KEYS.device,id)}return id}
async function ensureDeviceSession(force=false){if(!force&&await authStatus())return true;try{await api('/api/auth',{action:'bootstrap',deviceId:getDeviceId()});return await authStatus()}catch{authMeta={authenticated:false,provider:null};return false}}
let syncTimer;async function syncCloudNow(){if(!authMeta.authenticated)return false;try{const r=await api('/api/state',{action:'save',payload:{profile,plan,state,chat:typeof chat==='undefined'?[]:chat,cycleNumber:state.cycleNumber||1}});if(r.saved&&r.profile)profile={...freshOnboardingDraft(),...r.profile};if(r.saved&&r.plan)plan=r.plan;if(r.saved&&r.authoritativeStartedAt)state.startedAt=r.authoritativeStartedAt;if(r.saved&&r.cycleNumber)state.cycleNumber=Number(r.cycleNumber);state.sync={persistent:!!r.saved,lastSyncedAt:r.saved?new Date().toISOString():(state.sync?.lastSyncedAt||'')};saveJSON(KEYS.state,state);return !!r.saved}catch{return false}}
function scheduleCloudSync(){clearTimeout(syncTimer);syncTimer=setTimeout(()=>syncCloudNow(),650)}
async function loadCloudState(){if(!authMeta.authenticated)return false;try{const r=await api('/api/state',{action:'load'});if(!r?.data)return false;const d=r.data;if(d.profile&&d.plan){profile={...freshOnboardingDraft(),...d.profile};plan=d.plan;state=normalizeState(d.state);chat=Array.isArray(d.chat)?d.chat:[];lang=profile.language||lang;saveJSON(KEYS.profile,profile);saveJSON(KEYS.plan,plan);saveJSON(KEYS.state,state);saveJSON(KEYS.chat,chat);localStorage.setItem(KEYS.lang,lang)}state.sync={persistent:true,lastSyncedAt:d.updated_at||new Date().toISOString()};return true}catch{return false}}
function showOnly(id){['languageScreen','onboardingScreen','auditScreen','shell'].forEach(x=>$('#'+x).classList.toggle('hidden',x!==id))}
function appendTrace(entry){if(!entry)return;const rows=Array.isArray(state.traceLab)?state.traceLab:[];state.traceLab=[...rows.filter(x=>x?.traceId!==entry.traceId),entry].slice(-20)}

