 $('#auditTitle').innerHTML=L('Gerando seu primeiro mês<br><span style="color:var(--gold)">e auditando 3 vezes.</span>','Generating your first month<br><span style="color:var(--gold)">and auditing it 3 times.</span>','Generando tu primer mes<br><span style="color:var(--gold)">y auditándolo 3 veces.</span>');
 $('#auditCopy').textContent=L('Montamos um plano conservador com suas respostas e o passamos por três verificações. O Trace Lab registra a decisão com hashes e rota dos revisores — sem virar prescritor autônomo.','We build a conservative plan from your answers and run three checks. Trace Lab records the decision with hashes and reviewer routes — without becoming an autonomous prescriber.','Construimos un plan conservador con tus respuestas y ejecutamos tres controles. Trace Lab registra la decisión con hashes y rutas de revisores — sin convertirse en prescriptor autónomo.');
