 $('#settingsTitle').textContent=L('Configurações','Settings','Configuración');$('#coachKicker').textContent=L('BASEADO NO SEU SISTEMA','GROUNDED IN YOUR SYSTEM','BASADO EN TU SISTEMA');$('#coachText').placeholder=L('Pergunte sobre seu sistema…','Ask about your system…','Pregunta sobre tu sistema…');
 $('#coachNotice').textContent=L('O Coach usa o servidor quando a IA está configurada. Mudanças materiais continuam reviewable.','The Coach uses the server when AI is configured. Material changes remain reviewable.','El Coach usa el servidor cuando la IA está configurada. Los cambios materiales siguen sujetos a revisión.');
