function yesNoField(key,label,unresolved=false){const no=L('Não','No','No'),yes=unresolved?L('Sim / não resolvido','Yes / unresolved','Sí / no resuelto'):L('Sim','Yes','Sí');return `<div class="field"><label>${label}</label><div class="choiceGrid">${[['no',no],['yes',yes]].map(([k,v])=>`<button type="button" class="choice ${onboardingDraft[key]===k?'active':''}" data-choice="${key}" data-val="${k}">${v}</button>`).join('')}</div></div>`}
function showOnboarding(){showOnly('onboardingScreen');onboardingDraft.language=lang;onboardStep=0;renderStep()}
function syncDraft(){$$('#stepFields [data-f]').forEach(el=>{if(el.type==='checkbox')onboardingDraft[el.dataset.f]=el.checked;else onboardingDraft[el.dataset.f]=el.value})}
function renderStep(){const steps=stepDefs(),s=steps[onboardStep];$('#stepKicker').textContent=L(`PASSO ${onboardStep+1} DE 5`,`STEP ${onboardStep+1} OF 5`,`PASO ${onboardStep+1} DE 5`);$('#stepTitle').textContent=s.title;$('#stepCopy').textContent=s.copy;$('#stepFields').innerHTML=s.render();$('#onboardProgress').style.width=`${(onboardStep+1)*20}%`;$('#stepBack').disabled=onboardStep===0;$('#stepBack').textContent=L('Voltar','Back','Volver');$('#stepNext').textContent=onboardStep===4?L('Gerar e auditar →','Generate & audit →','Generar y auditar →'):L('Continuar →','Continue →','Continuar →');$$('[data-choice]').forEach(b=>b.onclick=()=>{syncDraft();onboardingDraft[b.dataset.choice]=b.dataset.val;renderStep()});$$('[data-day]').forEach(b=>b.onclick=()=>{syncDraft();const d=b.dataset.day;onboardingDraft.days=onboardingDraft.days.includes(d)?onboardingDraft.days.filter(x=>x!==d):[...onboardingDraft.days,d];renderStep()});$$('[data-multi]').forEach(b=>b.onclick=()=>{syncDraft();const f=b.dataset.multi,v=b.dataset.val,a=Array.isArray(onboardingDraft[f])?onboardingDraft[f]:[];onboardingDraft[f]=a.includes(v)?a.filter(x=>x!==v):[...a,v];renderStep()});$$('[data-bool]').forEach(b=>b.onclick=()=>{syncDraft();const f=b.dataset.bool;onboardingDraft[f]=!onboardingDraft[f];renderStep()})}
$('#stepBack').onclick=()=>{syncDraft();if(onboardStep>0){onboardStep--;renderStep()}};
function validateOnboardingStep(step){
 if(step===0&&(!onboardingDraft.name.trim()||!onboardingDraft.primaryGoal||!onboardingDraft.level||onboardingDraft.days.length<2))return L('Preencha nome, objetivo, nível e pelo menos 2 dias.','Complete name, goal, level and at least 2 days.','Completa nombre, objetivo, nivel y al menos 2 días.');
 if(step===1&&(!onboardingDraft.location||!onboardingDraft.minutes))return L('Selecione local e tempo realista de treino.','Select training location and realistic session time.','Selecciona lugar y tiempo realista de entrenamiento.');
 if(step===2&&(!onboardingDraft.meals||!onboardingDraft.cooking||!onboardingDraft.mealPrepPreference||!onboardingDraft.eatOutFrequency||!onboardingDraft.allergies.trim()))return L('Complete refeições, cozinha, meal prep, frequência de refeições fora e alergias/intolerâncias — escreva “nenhuma” se não houver.','Complete meals, cooking, meal prep, eating-out frequency and allergies/intolerances — write “none” if there are none.','Completa comidas, cocina, meal prep, frecuencia de comer fuera y alergias/intolerancias — escribe “ninguna” si no hay.');
 if(step===3){if(!onboardingDraft.sleep||!onboardingDraft.stress||!onboardingDraft.currentPain||!onboardingDraft.redFlags||!onboardingDraft.professionalRestrictions)return L('Responda sono, estresse e todas as perguntas de segurança.','Answer sleep, stress and every safety question.','Responde sueño, estrés y todas las preguntas de seguridad.');if(onboardingDraft.currentPain==='yes'&&!onboardingDraft.painAreas.length)return L('Selecione a área afetada para o plano poder se adaptar.','Select the affected area so the plan can adapt.','Selecciona la zona afectada para que el plan pueda adaptarse.');if(onboardingDraft.professionalRestrictions==='yes'&&!onboardingDraft.professionalRestrictionScope)return L('Informe o escopo da orientação profissional.','Select the scope of the professional guidance.','Selecciona el alcance de la indicación profesional.');if((onboardingDraft.currentPain==='yes'||onboardingDraft.redFlags==='yes'||onboardingDraft.professionalRestrictions==='yes')&&!onboardingDraft.safetyDetails.trim())return L('Adicione os detalhes mínimos necessários para orientar a revisão.','Add the minimum details needed to guide review.','Añade los detalles mínimos necesarios para orientar la revisión.')}
 return '';
}
$('#stepNext').onclick=()=>{syncDraft();const error=validateOnboardingStep(onboardStep);if(error){toast(error);return}if(onboardStep===4){if(!onboardingDraft.accuracy||!onboardingDraft.prototypeAck){toast(L('Confirme os dois itens.','Confirm both items.','Confirma ambos puntos.'));return}generateSystem();return}onboardStep++;renderStep()};

