function safetyRouting(p){const redFlag=p.redFlags==='yes',professionalNoExercise=p.professionalRestrictions==='yes'&&p.professionalRestrictionScope==='no_exercise',painReview=p.currentPain==='yes',professionalReview=p.professionalRestrictions==='yes'&&!professionalNoExercise,detailsReview=hasMeaningfulText(p.safetyDetails)&&!redFlag&&!professionalNoExercise,reasons=[];if(painReview)reasons.push('PAIN_LIMITATION');if(redFlag)reasons.push('RED_FLAG_SYMPTOM');if(professionalNoExercise)reasons.push('PROFESSIONAL_NO_EXERCISE');else if(professionalReview)reasons.push('PROFESSIONAL_GUIDANCE');if(detailsReview&&!painReview&&!professionalReview)reasons.push('SAFETY_DETAILS_REVIEW');const trainingRestricted=redFlag||professionalNoExercise,ownerReviewRequired=reasons.length>0;return {status:trainingRestricted?'RESTRICTED':ownerReviewRequired?'REVIEW_NOTIFY':'CLEAR',trainingRestricted,ownerReviewRequired,reasons,painAreas:[...(p.painAreas||[])],professionalRestrictionScope:p.professionalRestrictionScope||''}}
function preserveUnresolvedReview(previous,next){if(!previous)return next;const prev=previous.reviewRouting||{},cur=next.reviewRouting||{},mustPreserve=!!previous.trainingHold||prev.ownerReviewRequired===true;if(!mustPreserve)return next;const reasons=[...new Set([...(prev.reasons||[]),...(cur.reasons||[])])],restricted=!!previous.trainingHold||!!next.trainingHold||cur.trainingRestricted===true;next.reviewRouting={...cur,ownerReviewRequired:true,trainingRestricted:restricted,status:restricted?'RESTRICTED':'REVIEW_NOTIFY',reasons};next.trainingHold=restricted;next.training={...next.training,reviewRequired:true};if(restricted)next.risk='red';return next}
