 const route=safetyRouting(p),trainingHold=route.trainingRestricted,allergyReview=hasMeaningfulText(p.allergies),reviewRouting={...route,ownerReviewRequired:route.ownerReviewRequired||allergyReview,reasons:[...route.reasons,...(allergyReview?['ALLERGY_REVIEW']:[])]},risk=trainingHold?'red':(reviewRouting.ownerReviewRequired||Number(p.stress)>=5||['<5','5'].includes(p.sleep)?'yellow':'green'),tp=chooseTraining(p),coverage=catalogCoverage(p);
 const reuse=p.mealPrepPreference==='batch_cook'?'high':p.mealPrepPreference==='fresh_daily'?'low':'balanced',variety=p.mealPrepPreference==='fresh_daily'?'high':'balanced';
 return {version:APP_VERSION,createdAt:new Date().toISOString(),risk,trainingHold,allergyReview,reviewRouting,summary:{goal:goalLabel(p.primaryGoal),strengthDays:tp.strengthDays,selectedDays:tp.selectedDays,minutes:Number(p.minutes),location:p.location,meals:Number(p.meals),level:p.level,language:p.language},training:{pattern:tp.pattern,sets:tp.setBias,splitReason:tp.splitReason,progression:[L('Semana 1 • aprender e calibrar','Week 1 • learn & calibrate','Semana 1 • aprender y calibrar'),L('Semana 2 • consolidar técnica e repetições','Week 2 • build technique & reps','Semana 2 • consolidar técnica y repeticiones'),L('Semana 3 • progredir quando merecido; variação acessória limitada','Week 3 • progress when earned; limited accessory variation','Semana 3 • progresar cuando corresponda; variación accesoria limitada'),L('Semana 4 • consolidar e comparar desempenho','Week 4 • consolidate & compare performance','Semana 4 • consolidar y comparar rendimiento')],reviewRequired:route.ownerReviewRequired||trainingHold,painAware:{areas:route.painAreas,reviewStatus:route.status},adaptiveDesign:{cycle:1,preserveCoreAnchors:true,accessoryRotation:'bounded',volumePolicy:'calibrate'}},nutrition:{reviewRequired:allergyReview,weeks:4,meals:Number(p.meals),slotPolicy:'role-stable',principles:['role-stable meals','ingredient-aware optimization','purposeful rotation','substitutions','planned leftovers'],rotationSeed:1,catalogCoverage:coverage,optimizer:{cycle:1,ingredientReuse:reuse,variety},preferenceSnapshot:{proteins:p.proteinPreferences,grains:p.grainPreferences,vegetables:p.veggiePreferences,openToOtherVeggies:p.openToOtherVeggies,styles:p.foodStyles,mealPrep:p.mealPrepPreference,eatOut:p.eatOutFrequency}},catalog:{schema:'hercules-catalog-v1',strategy:{ingredientReuse:reuse,variety,reason:'Onboarding-driven base catalog strategy.'},meals:[],exercises:[],lastAdaptedCycle:1,provenance:'bundled-only'},recover:{sleep:p.sleep,stress:Number(p.stress)},mind:{focus:'sustainable consistency'},track:{signals:['sessions','difficulty/RIR','energy','sleep','nutrition adherence','symptoms','bounded notes']},evolve:{mode:'reviewable-adaptive-cycles',materialChangesAutomatic:false,safetyReleaseAutomatic:false},labQA:{mode:'decision-trace-v2',source:'Hercules Hub Decision Trace Laboratory',authority:'SUPERVISED_QA',promotion:'autonomous-authority-not-promoted'}}
