async function generateSystem(){const priorPlan=plan;profile={...onboardingDraft,language:lang,days:[...onboardingDraft.days],painAreas:[...(onboardingDraft.painAreas||[])]};plan=preserveUnresolvedReview(priorPlan,localPlan(profile));showOnly('auditScreen');applyStaticTranslations();const rows=[$('#audit1'),$('#audit2'),$('#audit3')],wait=L('AGUARDANDO','WAITING','ESPERANDO');rows.forEach(r=>{r.className='auditRow';r.querySelector('.auditState').textContent=wait});$('#enterGenerated').classList.add('hidden');$('#auditBack').classList.add('hidden');const local=localAudit(profile,plan);for(let i=0;i<3;i++){rows[i].classList.add('running');rows[i].querySelector('.auditState').innerHTML='<span class="spinner"></span>';await new Promise(r=>setTimeout(r,380));rows[i].classList.remove('running');rows[i].classList.add((local[i].verdict||'PASS').toLowerCase());rows[i].querySelector('.auditState').textContent=local[i].verdict}$('#auditMessage').textContent=L('QA local concluído. Criando trace e tentando auditoria de IA no servidor…','Local QA complete. Creating the trace and trying server AI audit…','QA local completo. Creando el trace e intentando auditoría de IA en el servidor…');let result={plan,audits:local,auditMode:'local+trace',labQA:plan.labQA};try{result=await api('/api/generate',{profile,plan});plan=preserveUnresolvedReview(priorPlan,result.plan||plan);const audits=result.audits||local;rows.forEach((r,i)=>{r.className='auditRow '+String(audits[i]?.verdict||'PASS').toLowerCase();r.querySelector('.auditState').textContent=audits[i]?.verdict||'PASS'});$('#auditMessage').textContent=['multi-provider+deterministic+trace','ai+deterministic+trace'].includes(result.auditMode)?L('Concluído: regras determinísticas + Trace Lab + até 3 passes de IA.','Complete: deterministic rules + Trace Lab + up to 3 AI passes.','Completo: reglas determinísticas + Trace Lab + hasta 3 pasadas de IA.'):L('Concluído com regras determinísticas + Trace Lab. IA não estava disponível.','Complete with deterministic rules + Trace Lab. AI was unavailable.','Completo con reglas determinísticas + Trace Lab. La IA no estaba disponible.')}catch{$('#auditMessage').textContent=L('IA indisponível. Os 3 gates determinísticos e o Trace Lab continuam ativos; nenhuma decisão de segurança foi promovida.','AI unavailable. Three deterministic gates and Trace Lab remain active; no safety decision was promoted.','IA no disponible. Los 3 gates determinísticos y Trace Lab siguen activos; no se promovió ninguna decisión de seguridad.')}menuCache.clear();const nutritionAudits=nutritionTripleAudit(),finalAudits=mergeNutritionAudit(result.audits||local,nutritionAudits),fatalBlock=finalAudits.some(a=>a?.verdict==='BLOCK');rows.forEach((r,i)=>{r.className='auditRow '+String(finalAudits[i]?.verdict||'PASS').toLowerCase();r.querySelector('.auditState').textContent=finalAudits[i]?.verdict||'PASS'});if(plan.reviewRouting?.ownerReviewRequired){const note=plan.trainingHold?L('TRAIN tem uma restrição controladora. O restante do sistema continua disponível quando aplicável.','TRAIN has a controlling restriction. The rest of the system remains available where appropriate.','TRAIN tiene una restricción controladora. El resto del sistema sigue disponible cuando corresponda.'):L('Plano criado com REVIEW. O caso foi marcado para revisão do Hercules sem travar todo o sistema.','Plan created with REVIEW. The case was marked for Hercules review without locking the whole system.','Plan creado con REVIEW. El caso fue marcado para revisión de Hercules sin bloquear todo el sistema.');$('#auditMessage').textContent+=' '+note}if(fatalBlock){$('#auditMessage').textContent+=' '+L('Existe um erro estrutural que precisa ser corrigido antes de entrar no sistema.','A structural error must be corrected before entering the system.','Hay un error estructural que debe corregirse antes de entrar al sistema.');$('#auditBack').classList.remove('hidden');return}const now=new Date().toISOString();state=normalizeState({...freshState(),startedAt:now,cycleNumber:1,week:1,nav:'HOME',trainingMode:profile.location==='home'?'home':'gym',audit:finalAudits,labQA:result.labQA||plan.labQA,traceLab:result.trace?[result.trace]:[],baseline:null});saveJSON(KEYS.profile,profile);saveJSON(KEYS.plan,plan);saveJSON(KEYS.state,state);scheduleCloudSync();$('#enterGenerated').classList.remove('hidden')}

$('#enterGenerated').onclick=()=>showApp();$('#auditBack').onclick=()=>showOnboarding();

