 'romanian-deadlift-home':[['Terra romeno em casa','Home Romanian deadlift','Peso muerto rumano en casa'],['Pés firmes, joelhos suaves, carga junto às pernas.','Feet planted, soft knees, load close to legs.','Pies firmes, rodillas suaves, carga cerca de las piernas.'],['Empurre o quadril para trás mantendo coluna neutra; volte contraindo glúteos.','Push hips back with neutral spine; return by squeezing glutes.','Lleva cadera atrás con columna neutra; vuelve apretando glúteos.'],['Posteriores, glúteos','Hamstrings, glutes','Isquiotibiales, glúteos']],
 'reverse-lunge-home':[['Afundo reverso em casa','Home reverse lunge','Zancada inversa en casa'],['Use apoio se necessário, pé da frente estável e espaço livre atrás.','Use support if needed, stable front foot, clear space behind.','Usa apoyo si hace falta, pie delantero estable y espacio libre atrás.'],['Dê passo para trás, desça com controle e retorne pela perna da frente.','Step back, lower under control, return through front leg.','Da un paso atrás, baja con control y vuelve con la pierna delantera.'],['Quadríceps, glúteos','Quads, glutes','Cuádriceps, glúteos']],
 'glute-bridge':[['Ponte de glúteos','Glute bridge','Puente de glúteos'],['Deite com pés firmes próximos do quadril e joelhos flexionados.','Lie with feet planted near hips and knees bent.','Acuéstate con pies firmes cerca de la cadera y rodillas flexionadas.'],['Eleve o quadril contraindo glúteos sem hiperestender a lombar; desça devagar.','Raise hips by squeezing glutes without overextending low back; lower slowly.','Eleva la cadera apretando glúteos sin hiperextender la lumbar; baja lento.'],['Glúteos, posteriores','Glutes, hamstrings','Glúteos, isquiotibiales']],
 'bird-dog':[['Bird dog','Bird dog','Bird dog'],['Quatro apoios, mãos sob ombros e joelhos sob quadris.','All fours, hands under shoulders, knees under hips.','Cuatro apoyos, manos bajo hombros y rodillas bajo caderas.'],['Estenda braço e perna opostos sem girar o tronco; retorne e alterne.','Extend opposite arm and leg without rotating torso; return and alternate.','Extiende brazo y pierna opuestos sin girar el torso; vuelve y alterna.'],['Core, quadril','Core, hips','Core, cadera']],
