function foodScoreFor(x,p){if(!foodAllowedByPreferences(x,p))return -999;const m=x?.[3]||{},pp=p?.proteinPreferences||[],gp=p?.grainPreferences||[],vp=p?.veggiePreferences||[],sp=p?.foodStyles||[];let score=0;if(m.protein)score+=pp.includes(m.protein)?5:(pp.length?-2:0);if(m.grain)score+=gp.includes(m.grain)?3:0;if(m.styles?.some(v=>sp.includes(v)))score+=2;if(m.veggies?.length)score+=m.veggies.filter(v=>vp.includes(v)).length*.8;if(p?.openToOtherVeggies===false&&m.veggies?.length&&!m.veggies.every(v=>vp.includes(v)))score-=3;return score}
