function menuFingerprint(){return JSON.stringify({cycle:state.cycleNumber||1,seed:plan?.nutrition?.rotationSeed||1,prep:profile?.mealPrepPreference||'mixed',food:profile?.foodPreferences||'',dislikes:profile?.dislikes||'',proteins:profile?.proteinPreferences||[],grains:profile?.grainPreferences||[],veggies:profile?.veggiePreferences||[],open:profile?.openToOtherVeggies!==false,styles:profile?.foodStyles||[],cook:profile?.cooking||'',eat:profile?.eatOutFrequency||'',catalog:(plan?.catalog?.meals||[]).map(m=>[m.id,m.createdForCycle,m.assetStatus||'']).sort()})}
function monthMenu(){const key=menuFingerprint();if(menuCache.has(key))return menuCache.get(key);const tokens=dislikeTokens(),recentByRole={breakfast:[],lunch:[],snack:[],dinner:[]},monthMealUse={},monthIngredientUse={},weeks=[],reuse=plan?.nutrition?.optimizer?.ingredientReuse||plan?.catalog?.strategy?.ingredientReuse||'balanced',variety=plan?.nutrition?.optimizer?.variety||plan?.catalog?.strategy?.variety||'balanced',reuseBonus=reuse==='high'?1.4:reuse==='low'?.15:.65,variationBonus=variety==='high'?1.15:.45;let previousWeekMeals=new Set();for(let week=1;week<=4;week++){const weekUse={},weekMeals=new Set(),days=[];for(let day=0;day<7;day++){const seen={},rows=[];for(const role of mealRoles()){seen[role]=(seen[role]||0)+1;const list=availableFood(role),candidates=list.filter(x=>{if(!foodAllowedByPreferences(x,profile))return false;const searchable=(x[1].join(' ')+' '+((x?.[3]?.ingredients||[]).join(' '))).toLowerCase();return !tokens.some(t=>searchable.includes(t))}).map(x=>{const ids=ingredientKeys(x),recent=recentByRole[role]||[],repeatPenalty=recent.slice(-3).includes(x[0])?12:0,mealUsePenalty=(monthMealUse[x[0]]||0)*.65,weeklyIngredientBonus=ids.reduce((n,k)=>n+(weekUse[k]?reuseBonus:0),0),monthOveruse=ids.reduce((n,k)=>n+(monthIngredientUse[k]>=10?.7:0),0),newWeek=week>1&&!previousWeekMeals.has(x[0])?variationBonus:0,sourceBonus=x?.[3]?.source==='ai-generated'?0:.2;return {x,score:foodScore(x)+weeklyIngredientBonus+newWeek-repeatPenalty-mealUsePenalty-monthOveruse+sourceBonus+stableTie(key+':'+week+':'+day+':'+role+':'+x[0])*.08}});candidates.sort((a,b)=>b.score-a.score);const chosen=candidates[0]?.x;if(chosen){recentByRole[role].push(chosen[0]);monthMealUse[chosen[0]]=(monthMealUse[chosen[0]]||0)+1;weekMeals.add(chosen[0]);ingredientKeys(chosen).forEach(k=>{weekUse[k]=(weekUse[k]||0)+1;monthIngredientUse[k]=(monthIngredientUse[k]||0)+1});rows.push({role,item:chosen,occurrence:seen[role]})}}days.push(rows)}weeks.push(days);previousWeekMeals=weekMeals}menuCache.set(key,weeks);if(menuCache.size>10)menuCache.delete(menuCache.keys().next().value);return weeks}
