function completion(){const total=plan?.training?.pattern?.length||0,done=new Set(Object.entries(state.completedSessions||{}).filter(([,v])=>v===true).map(([k])=>canonicalSessionIdentity(k))).size,tr=total?Math.min(100,Math.round(done/(total*4)*100)):0,rows=normalizeDailyCheckins(state.checkins),expected=Math.min(28,Math.max(1,elapsedDays()+1)),track=Math.min(100,Math.round(rows.length/expected*100));return{tr,track,overall:Math.min(100,Math.round(tr*.65+track*.35))}}
function currentWeek(){if(!state.startedAt)return 1;const d=Math.floor((Date.now()-new Date(state.startedAt).getTime())/604800000)+1;return Math.max(1,Math.min(4,d))}
